-- Loads the cimgui shared library through the LuaJIT FFI. This module is the template for binding
-- any foreign library: declarations (`cimgui.ffi.h`, generated by build/generateBindings.py) are
-- handed to `ffi.cdef` once, and the platform binary shipped under `native/<os>-<arch>/` is
-- loaded from a content-addressed cache in the save directory (a library inside an archive
-- cannot be dlopen'ed).
--
-- Library.load() returns { ffi, C, hash, platform } or nil and the reason (no binary for this
-- platform, ...), so the engine can run without the plugin's native part.
local ffi = require('ffi')

local Library = {}

local ROOT = 'source/plugins/imgui/'
local state

local function loadBinary()
    local os, architecture = katsa.system.getOS(), ffi.arch
    local platform = ({ Windows = 'win', Linux = 'linux', Android = 'android', ['OS X'] = 'osx' })[os]
    local arch = ({ x64 = 'x64', arm64 = 'arm64', arm = 'arm' })[architecture]
    assert(platform and arch, 'No ImGui binary for ' .. os .. '/' .. architecture)
    local filename = os == 'Windows' and 'cimgui.dll'
        or os == 'OS X' and 'libcimgui.dylib'
        or 'libcimgui.so'
    local relative = ROOT .. 'native/' .. platform .. '-' .. arch .. '/' .. filename
    local bytes = katsa.filesystem.read(relative)
    local library
    if os == 'Android' then
        -- A library packaged in the APK's native-lib directory loads by name.
        local ok, packaged = pcall(ffi.load, 'cimgui')
        library = ok and packaged or nil
    end
    local hash = 'packaged'
    if not library then
        assert(bytes, 'Missing ImGui native library: ' .. relative .. ' (see ' .. ROOT .. 'README.md)')
        hash = require('source.engine.core.fingerprint').of(bytes)
        local folder = 'native-cache/cimgui-' .. hash
        assert(katsa.filesystem.createDirectory(folder))
        local target = folder .. '/' .. filename
        if katsa.filesystem.read(target) ~= bytes then
            assert(katsa.filesystem.write(target, bytes))
        end
        library = require('source.katsa.core.native').loadFile(
            katsa.filesystem.getSaveDirectory() .. '/' .. target
        )
    end
    return { ffi = ffi, C = library, hash = hash, platform = platform .. '-' .. arch }
end

function Library.load()
    if state == nil then
        local ok, result = pcall(function()
            -- Parenthesized: the read returns the byte count too, and cdef takes one string.
            ffi.cdef((assert(katsa.filesystem.read(ROOT .. 'binding/cimgui.ffi.h'))))
            return loadBinary()
        end)
        state = ok and result or { failure = tostring(result) }
    end
    if state.failure then
        return nil, state.failure
    end
    return state
end

return Library
